describe('Image Upload - Small Dimensions Error', () => {
  beforeEach(() => {
    cy.visit('/upload-image');
  });

  it('should display error message when image dimensions are too small', () => {
    // Intercept the API call to upload image
    cy.intercept('POST', '/api/upload/image', {
      statusCode: 200,
      body: {
        error: 'Image dimensions are too small',
        message: 'Minimum width and height are 100px'
      }
    }).as('uploadError');

    // Attempt to upload a small image
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/small-image.jpg', { force: true });
    cy.get('[data-testid="upload-button"]').click();

    // Wait for the error response
    cy.wait('@uploadError');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Image dimensions are too small');

    // Verify error icon is visible
    cy.get('[data-testid="error-icon"]').should('be.visible');

    // Verify success button is disabled
    cy.get('[data-testid="success-button"]').should('be.disabled');
  });

  it('should not display error when image dimensions are acceptable', () => {
    // Intercept the API call to upload image
    cy.intercept('POST', '/api/upload/image', {
      statusCode: 200,
      body: {
        success: true,
        message: 'Image uploaded successfully'
      }
    }).as('uploadSuccess');

    // Attempt to upload a medium-sized image
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/medium-image.jpg', { force: true });
    cy.get('[data-testid="upload-button"]').click();

    // Wait for the success response
    cy.wait('@uploadSuccess');

    // Verify success message is displayed
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Image uploaded successfully');

    // Verify error message is not displayed
    cy.get('[data-testid="error-message"]').should('not.exist');

    // Verify success button is enabled
    cy.get('[data-testid="success-button"]').should('be.enabled');
  });
});
